#!/bin/bash
# GitLab Runner (shell executor) for Railway.
#
# Railway has no Docker-in-Docker, so this runner uses the shell executor: jobs
# run directly inside this container as the `gitlab-runner` user, with the tools
# installed in the Dockerfile. The `image:` keyword in .gitlab-ci.yml is ignored.
#
# Registration (first boot, config.toml kept on the volume):
#   1. GITLAB_RUNNER_TOKEN set (a glrt-... token from GitLab's "New instance runner"
#      page): register with it.
#   2. Otherwise, GITLAB_RUNNER_BOOTSTRAP_TOKEN set (generated by the template and
#      planted in GitLab by the GitLab service): create an instance runner
#      through the API, register it, then revoke the bootstrap token.
#   3. Neither: wait and explain what to do.
set -euo pipefail

CONFIG_DIR=/etc/gitlab-runner
RUNNER_CONFIG="${CONFIG_DIR}/config.toml"
GITLAB_URL="${GITLAB_INTERNAL_URL:?GITLAB_INTERNAL_URL is required (e.g. http://gitlab.railway.internal)}"
GITLAB_URL="${GITLAB_URL%/}"
GITLAB_RUNNER_NAME="${GITLAB_RUNNER_NAME:-railway-shell-runner}"
GITLAB_RUNNER_DESCRIPTION="${GITLAB_RUNNER_DESCRIPTION:-Railway shell runner}"
GITLAB_RUNNER_TAGS="${GITLAB_RUNNER_TAGS:-railway,shell}"
GITLAB_RUNNER_RUN_UNTAGGED="${GITLAB_RUNNER_RUN_UNTAGGED:-true}"
GITLAB_RUNNER_CONCURRENT="${GITLAB_RUNNER_CONCURRENT:-2}"

log() { echo "[railway-runner] $*"; }

mkdir -p "$CONFIG_DIR"
rm -rf "${CONFIG_DIR}/lost+found"

wait_for_gitlab() {
  local n=0
  until [ "$(curl -s -o /dev/null -w '%{http_code}' "${GITLAB_URL}/users/sign_in" || true)" = "200" ]; do
    if [ $((n % 6)) -eq 0 ]; then log "waiting for GitLab at ${GITLAB_URL} ..."; fi
    n=$((n + 1))
    sleep 10
  done
  log "GitLab is reachable"
}

registered_token() {
  # Prints the token of the first runner in config.toml, if any.
  [ -f "$RUNNER_CONFIG" ] || return 0
  sed -n 's/^[[:space:]]*token = "\(glrt-[^"]*\)".*/\1/p' "$RUNNER_CONFIG" | head -n1
}

register() {
  local token="$1"
  rm -f "$RUNNER_CONFIG"
  gitlab-runner register \
    --non-interactive \
    --config "$RUNNER_CONFIG" \
    --url "$GITLAB_URL" \
    --clone-url "$GITLAB_URL" \
    --token "$token" \
    --name "$GITLAB_RUNNER_NAME" \
    --executor shell \
    --shell bash \
    --request-concurrency "${GITLAB_RUNNER_REQUEST_CONCURRENCY:-2}"
  log "registered runner '${GITLAB_RUNNER_NAME}' against ${GITLAB_URL}"
}

create_runner_with_bootstrap_token() {
  # Retries until GitLab has created the bootstrap token (it does so a few
  # minutes after its first successful boot).
  local response status body
  while true; do
    response=$(curl -s -w '\n%{http_code}' -X POST \
      -H "PRIVATE-TOKEN: ${GITLAB_RUNNER_BOOTSTRAP_TOKEN}" \
      --data-urlencode "runner_type=instance_type" \
      --data-urlencode "description=${GITLAB_RUNNER_DESCRIPTION}" \
      --data-urlencode "tag_list=${GITLAB_RUNNER_TAGS}" \
      --data-urlencode "run_untagged=${GITLAB_RUNNER_RUN_UNTAGGED}" \
      "${GITLAB_URL}/api/v4/user/runners" || true)
    status=$(printf '%s' "$response" | tail -n1)
    body=$(printf '%s' "$response" | sed '$d')
    case "$status" in
      201)
        NEW_TOKEN=$(printf '%s' "$body" | jq -r '.token')
        log "created instance runner #$(printf '%s' "$body" | jq -r '.id') through the API"
        return 0
        ;;
      401)
        log "bootstrap token not accepted yet (GitLab creates it after its first boot); retrying in 30s"
        ;;
      *)
        log "runner creation failed (HTTP ${status}): ${body}; retrying in 60s"
        sleep 30
        ;;
    esac
    sleep 30
  done
}

wait_for_gitlab

current_token="$(registered_token)"
if [ -n "${GITLAB_RUNNER_TOKEN:-}" ]; then
  if [ "$current_token" != "$GITLAB_RUNNER_TOKEN" ]; then
    register "$GITLAB_RUNNER_TOKEN"
  fi
elif [ -z "$current_token" ]; then
  if [ -n "${GITLAB_RUNNER_BOOTSTRAP_TOKEN:-}" ]; then
    NEW_TOKEN=""
    create_runner_with_bootstrap_token
    register "$NEW_TOKEN"
    # The bootstrap token has done its job; revoke it (best effort).
    curl -s -o /dev/null -w '[railway-runner] bootstrap token revoke: HTTP %{http_code}\n' \
      -X DELETE -H "PRIVATE-TOKEN: ${GITLAB_RUNNER_BOOTSTRAP_TOKEN}" \
      "${GITLAB_URL}/api/v4/personal_access_tokens/self" || true
  else
    log "No runner registered and no token given."
    log "In GitLab: Admin area > CI/CD > Runners > New instance runner, copy the glrt-... token,"
    log "set it as GITLAB_RUNNER_TOKEN on this service and redeploy."
    exec sleep infinity
  fi
else
  log "using the runner already registered in ${RUNNER_CONFIG}"
fi

# Global settings managed from variables.
sed -i "s/^concurrent = .*/concurrent = ${GITLAB_RUNNER_CONCURRENT}/" "$RUNNER_CONFIG"
sed -i "s/^check_interval = .*/check_interval = ${GITLAB_RUNNER_CHECK_INTERVAL:-3}/" "$RUNNER_CONFIG"

# The tokens are in config.toml now; keep them out of the job environment.
unset GITLAB_RUNNER_TOKEN GITLAB_RUNNER_BOOTSTRAP_TOKEN

exec gitlab-runner run \
  --config "$RUNNER_CONFIG" \
  --user gitlab-runner \
  --working-directory /home/gitlab-runner
